using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
namespace Underwater.Editor {
public static class ReducedLionfishIntegration {
 public const string Scene="Assets/Scenes/Underwater_Realistic.unity",Folder="Assets/UnderwaterArt/GameplayLionfish/";
 static SeaLife Fish()=>UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Single(a=>a.kind=="Lionfish");
 static Vector3[] Points(SkinnedMeshRenderer skin){var mesh=skin.sharedMesh;var matrices=skin.bones.Select((b,i)=>b.localToWorldMatrix*mesh.bindposes[i]).ToArray();var vertices=mesh.vertices;var weights=mesh.boneWeights;for(int i=0;i<vertices.Length;i++){var w=weights[i];var v=vertices[i];vertices[i]=matrices[w.boneIndex0].MultiplyPoint3x4(v)*w.weight0+matrices[w.boneIndex1].MultiplyPoint3x4(v)*w.weight1+matrices[w.boneIndex2].MultiplyPoint3x4(v)*w.weight2+matrices[w.boneIndex3].MultiplyPoint3x4(v)*w.weight3;}return vertices;}
 static string[] Ids(GameObject root)=>root.GetComponentsInChildren<Transform>(true).SelectMany(t=>t.GetComponents<Component>().Cast<UnityEngine.Object>().Prepend(t.gameObject)).Where(o=>o).Select(o=>GlobalObjectId.GetGlobalObjectIdSlow(o).targetObjectId.ToString()).Distinct().ToArray();
 public static void Integrate(){
  var scene=EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory("Renders/GameplayLionfish");var life=Fish();File.WriteAllLines("Renders/GameplayLionfish/BeforeIds.txt",Ids(life.gameObject));var zone=life.GetComponent<ReefDangerZone>();var indicator=zone.cautionIndicator;indicator.SetParent(life.transform,true);var outlineMaterial=zone.outlines.First(l=>l).sharedMaterial;var oldRenderers=life.GetComponentsInChildren<MeshRenderer>();var oldBounds=oldRenderers[0].bounds;foreach(var r in oldRenderers)oldBounds.Encapsulate(r.bounds);float length=Mathf.Clamp(oldBounds.size.z,.65f,1.15f);Vector3 oldPosition=life.transform.position;
  foreach(var child in life.transform.Cast<Transform>().ToArray())if(child!=indicator)UnityEngine.Object.DestroyImmediate(child.gameObject);if(life.GetComponent<FishBodyMotion>())UnityEngine.Object.DestroyImmediate(life.GetComponent<FishBodyMotion>());if(life.GetComponent<MeshRenderer>())UnityEngine.Object.DestroyImmediate(life.GetComponent<MeshRenderer>());if(life.GetComponent<MeshFilter>())UnityEngine.Object.DestroyImmediate(life.GetComponent<MeshFilter>());
  var importer=(ModelImporter)AssetImporter.GetAtPath(Folder+"Lionfish.fbx");importer.animationType=ModelImporterAnimationType.Legacy;importer.importAnimation=true;importer.importCameras=false;importer.importLights=false;importer.materialImportMode=ModelImporterMaterialImportMode.None;importer.meshCompression=ModelImporterMeshCompression.Off;importer.animationCompression=ModelImporterAnimationCompression.Off;importer.isReadable=true;var clips=importer.defaultClipAnimations;foreach(var c in clips){c.name="CoordinatedSwim";c.loopTime=true;c.wrapMode=WrapMode.Loop;}importer.clipAnimations=clips;importer.SaveAndReimport();
  foreach(string name in new[]{"Albedo.png","Normal.png"}){var ti=(TextureImporter)AssetImporter.GetAtPath(Folder+name);ti.maxTextureSize=2048;ti.mipmapEnabled=true;ti.streamingMipmaps=true;ti.textureCompression=TextureImporterCompression.CompressedHQ;if(name=="Normal.png")ti.textureType=TextureImporterType.NormalMap;var platform=ti.GetPlatformTextureSettings("Android");platform.name="Android";platform.overridden=true;platform.maxTextureSize=2048;platform.format=TextureImporterFormat.ASTC_6x6;ti.SetPlatformTextureSettings(platform);ti.SaveAndReimport();}
  var skinMaterial=new Material(Shader.Find("Underwater/Quest Reef")){name="Gameplay lionfish skin",enableInstancing=true};skinMaterial.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"Albedo.png");skinMaterial.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"Normal.png"));skinMaterial.SetFloat("_BumpScale",.45f);skinMaterial.SetFloat("_Cull",0);skinMaterial.SetColor("_Color",Color.white);AssetDatabase.CreateAsset(skinMaterial,Folder+"Skin.mat");
  var visual=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"Lionfish.fbx"));visual.name="Reduced bilateral lionfish visual";visual.transform.SetParent(life.transform,false);visual.transform.localRotation=Quaternion.Euler(0,180,0);var skin=visual.GetComponentInChildren<SkinnedMeshRenderer>();skin.sharedMaterial=skinMaterial;skin.shadowCastingMode=ShadowCastingMode.Off;skin.receiveShadows=false;skin.updateWhenOffscreen=false;skin.lightProbeUsage=LightProbeUsage.Off;skin.reflectionProbeUsage=ReflectionProbeUsage.Off;
  var clip=AssetDatabase.LoadAllAssetsAtPath(Folder+"Lionfish.fbx").OfType<AnimationClip>().First(c=>!c.name.StartsWith("__"));clip.SampleAnimation(visual,0);var fp=Points(skin);var fitted=new Bounds(fp[0],Vector3.zero);foreach(var p in fp)fitted.Encapsulate(p);Debug.Log("LIONFISH_RAW_FIT "+fitted+" skinScale="+skin.transform.lossyScale);visual.transform.localScale=Vector3.one*(length/fitted.size.z);fp=Points(skin);fitted=new Bounds(fp[0],Vector3.zero);foreach(var p in fp)fitted.Encapsulate(p);visual.transform.localPosition-=life.transform.InverseTransformPoint(fitted.center);var animation=visual.GetComponent<Animation>();if(animation)animation.enabled=false;
  bool first=true;Bounds envelope=default,localEnvelope=default;var samples=new System.Collections.Generic.List<Vector3>();var mesh=new Mesh();for(int p=0;p<=24;p++){clip.SampleAnimation(visual,clip.length*p/24f);foreach(var world in Points(skin)){var v=skin.transform.InverseTransformPoint(world);var point=life.transform.InverseTransformPoint(world);samples.Add(point);if(first){envelope=new Bounds(point,Vector3.zero);localEnvelope=new Bounds(v,Vector3.zero);first=false;}else {envelope.Encapsulate(point);localEnvelope.Encapsulate(v);}}}UnityEngine.Object.DestroyImmediate(mesh);clip.SampleAnimation(visual,0);envelope.Expand(.04f);localEnvelope.Expand(.04f/Mathf.Max(.0001f,skin.transform.lossyScale.x));skin.localBounds=localEnvelope;var guard=life.GetComponent<ReefAnimalClearance>();guard.animatedBody=envelope;var body=life.GetComponent<ReefSphereBody>();body.centerOffset=envelope.center;body.radius=new Vector2(envelope.extents.x,envelope.extents.z).magnitude*life.transform.lossyScale.x;guard.Enforce();Physics.SyncTransforms();if(!body.Clear(life.transform.position)&&!body.PlaceNear(life.transform.position))throw new Exception("Cannot preserve clear lionfish habitat");
  var touchGo=new GameObject("Lionfish body touch volume");touchGo.transform.SetParent(life.transform,false);touchGo.layer=9;var touch=touchGo.AddComponent<CapsuleCollider>();touch.direction=2;touch.center=envelope.center;touch.radius=envelope.extents.y*.52f;touch.height=envelope.size.z*.75f;touch.isTrigger=true;var contact=life.GetComponent<FishTouchBody>();contact.touchCollider=touch;contact.bodyBounds=new Bounds(envelope.center,Vector3.Scale(envelope.size,new Vector3(.6f,.65f,.8f)));
  var solidGo=UnityEngine.Object.Instantiate(touchGo,life.transform);solidGo.name="Lionfish solid body";solidGo.GetComponent<Collider>().isTrigger=false;
  Debug.Log("LIONFISH_ENVELOPE "+envelope+" samples="+samples.Count+" visualScale="+visual.transform.localScale);var surfaces=new System.Collections.Generic.List<Collider>();var outlines=new System.Collections.Generic.List<LineRenderer>();for(int part=0;part<3;part++){var pts=samples.Where(p=>part==0?p.y>envelope.center.y+envelope.extents.y*.3f:part==1?p.x<envelope.center.x-envelope.extents.x*.35f:p.x>envelope.center.x+envelope.extents.x*.35f).ToArray();if(pts.Length==0)throw new Exception("Missing spine surface part="+part+" envelope="+envelope);var b=new Bounds(pts[0],Vector3.zero);foreach(var p in pts)b.Encapsulate(p);var go=new GameObject(part==0?"Dorsal spine warning surface":part==1?"Left fin warning surface":"Right fin warning surface");go.transform.SetParent(life.transform,false);go.layer=2;var box=go.AddComponent<BoxCollider>();box.center=b.center;box.size=b.size;box.isTrigger=true;surfaces.Add(box);var line=go.AddComponent<LineRenderer>();line.sharedMaterial=outlineMaterial;line.useWorldSpace=false;line.loop=true;line.widthMultiplier=.006f;line.positionCount=4;line.SetPositions(new[]{b.center+new Vector3(-b.extents.x,b.extents.y,-b.extents.z),b.center+new Vector3(b.extents.x,b.extents.y,-b.extents.z),b.center+new Vector3(b.extents.x,b.extents.y,b.extents.z),b.center+new Vector3(-b.extents.x,b.extents.y,b.extents.z)});line.enabled=false;outlines.Add(line);}
  zone.surfaces=surfaces.ToArray();zone.outlines=outlines.ToArray();zone.glowTargets=Array.Empty<Renderer>();indicator.localPosition=new Vector3(envelope.center.x,envelope.max.y+.12f,envelope.center.z);var encounter=life.GetComponent<ReefEncounter>();encounter.skin=new Renderer[]{skin};encounter.tentacles=Array.Empty<Transform>();var motion=life.gameObject.AddComponent<LionfishTravelAnimation>();motion.visual=visual;motion.clip=clip;var lod=visual.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.022f,new Renderer[]{skin})});lod.RecalculateBounds();
  AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);File.WriteAllLines("Renders/GameplayLionfish/AfterIds.txt",Ids(life.gameObject));File.WriteAllText("Renders/GameplayLionfish/Placement.txt","Original="+oldPosition+" integrated="+life.transform.position+" length="+length+" envelope="+envelope+" radius="+body.radius);Validate();Capture();
 }
 public static void Validate(){
  EditorSceneManager.OpenScene(Scene);var life=Fish();var motion=life.GetComponent<LionfishTravelAnimation>();if(!motion)throw new Exception("Missing locomotion/animation sync");var skin=motion.visual.GetComponentInChildren<SkinnedMeshRenderer>();if(skin.sharedMesh.triangles.Length/3!=20022||skin.bones.Length!=9||life.grabbable||!life.danger)throw new Exception("Model/gameplay identity changed");var body=life.GetComponent<ReefSphereBody>();var encounter=life.GetComponent<ReefEncounter>();Physics.SyncTransforms();var origin=life.transform.position;float distance=0,minHeading=1,maxRate=0;for(int frame=0;frame<2400;frame++){var before=life.transform.position;encounter.Step(1f/30,life.transform.position-life.transform.forward*.3f,frame==360?.3f:10);motion.StepVisual(1f/30);Physics.SyncTransforms();if(!body.Clear(life.transform.position))throw new Exception("Lionfish overlaps reef/seabed");var delta=life.transform.position-before;distance+=delta.magnitude;maxRate=Mathf.Max(maxRate,motion.PlaybackRate);if(Vector3.ProjectOnPlane(delta,Vector3.up).sqrMagnitude>.000001f)minHeading=Mathf.Min(minHeading,Vector3.Dot(Vector3.ProjectOnPlane(delta,Vector3.up).normalized,Vector3.ProjectOnPlane(life.transform.forward,Vector3.up).normalized));}
  if(distance<2||minHeading<-.1f||maxRate<.3f)throw new Exception("Lionfish locomotion stalled or moving backwards: distance="+distance+" heading="+minHeading);motion.MatchTravel(0);for(int i=0;i<120;i++)motion.StepVisual(1f/30);float stopped=motion.SwimClock,breathing=motion.BreathClock;for(int i=0;i<30;i++)motion.StepVisual(1f/30);if(motion.SwimClock-stopped>.001f||motion.BreathClock-breathing<.9f)throw new Exception("Stopped travel/breathing clocks are coupled");var zone=life.GetComponent<ReefDangerZone>();if(zone.surfaces.Length!=3||zone.surfaces.Any(c=>!c)||!zone.cautionIndicator)throw new Exception("Spine warnings missing");var warning=zone.Step(0,100,true);if(!warning.warn)throw new Exception("Warning missing");zone.MarkWarningSpoken(100);if(!zone.Step(0,101,true).contact)throw new Exception("Spine consequence missing");
  Directory.CreateDirectory("Renders/GameplayLionfish");File.WriteAllText("Renders/GameplayLionfish/Validation.txt","Reduced fish=20022 triangles, 9 bones, 1 skin/material.\n80-second encounter patrol/retreat: distance="+distance+" min forward alignment="+minHeading+" max playback rate="+maxRate+"\nCollision/seabed clearance, warning/contact flow, movement-linked body/tail cycle and independent breathing at rest passed.\nNo preview-only playback component, no runtime mesh baking, no added light/shadow. Device FPS not measured.\n");EditorSceneManager.OpenScene(Scene);RealisticReefBuilder.ValidateScene();ReefCollisionValidation.Run();Debug.Log("GAMEPLAY_LIONFISH_VALIDATED distance="+distance+" minHeading="+minHeading);
 }
 public static void Capture(){EditorSceneManager.OpenScene(Scene);var life=Fish();var motion=life.GetComponent<LionfishTravelAnimation>();motion.Initialize();motion.MatchTravel(.2f);for(int i=0;i<20;i++)motion.StepVisual(1f/30);var skin=motion.visual.GetComponentInChildren<SkinnedMeshRenderer>();var center=skin.bounds.center;var camera=Camera.main;var optics=camera.GetComponent<ReefOptics>();if(optics)optics.enabled=false;camera.transform.position=center+life.transform.right*1.8f+life.transform.forward*.8f+Vector3.up*.3f;camera.transform.LookAt(center);camera.fieldOfView=48;camera.nearClipPlane=.01f;ReefCorrectionAudit.Capture(camera,"Renders/GameplayLionfish/InHabitat.png");}
 public static void RefineBounds(){var scene=EditorSceneManager.OpenScene(Scene);var life=Fish();var motion=life.GetComponent<LionfishTravelAnimation>();var skin=motion.visual.GetComponentInChildren<SkinnedMeshRenderer>();var b=life.GetComponent<ReefAnimalClearance>().animatedBody;bool first=true;Bounds local=default;for(int i=0;i<8;i++){var corner=b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1));var p=skin.transform.InverseTransformPoint(life.transform.TransformPoint(corner));if(first){local=new Bounds(p,Vector3.zero);first=false;}else local.Encapsulate(p);}skin.localBounds=local;var lod=motion.visual.GetComponent<LODGroup>();lod.RecalculateBounds();EditorSceneManager.SaveScene(scene);Debug.Log("GAMEPLAY_LIONFISH_BOUNDS_REFINED worldSize="+skin.bounds.size+" lodSize="+lod.size);Validate();}
 public static void Inspect(){EditorSceneManager.OpenScene(Scene);var life=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Single(a=>a.kind=="Lionfish");var report=new System.Text.StringBuilder();foreach(var t in life.GetComponentsInChildren<Transform>(true))report.AppendLine(t.name+" local="+t.localPosition+" scale="+t.localScale+" components="+string.Join(",",t.GetComponents<Component>().Select(c=>c?c.GetType().Name:"MISSING")));report.AppendLine("Actor "+life.transform.position+" rotation="+life.transform.eulerAngles);var body=life.GetComponent<ReefSphereBody>();report.AppendLine("Sphere radius="+body.radius+" offset="+body.centerOffset);var danger=life.GetComponent<ReefDangerZone>();report.AppendLine("Hazard surfaces="+string.Join(",",danger.surfaces.Select(c=>c?c.name:"NULL"))+" indicator="+(danger.cautionIndicator?danger.cautionIndicator.name:"none"));Directory.CreateDirectory("Renders/GameplayLionfish");File.WriteAllText("Renders/GameplayLionfish/Before.txt",report.ToString());Debug.Log("LIONFISH_INSPECTED");}
}
}
